CREATE TABLE wechat_secret (id BIGINT PRIMARY KEY AUTO_INCREMENT, purpose VARCHAR(40) NOT NULL, nonce VARBINARY(12) NOT NULL, ciphertext MEDIUMBLOB NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
ALTER TABLE wechat_config ADD COLUMN user_secret_id BIGINT, ADD COLUMN merchant_secret_id BIGINT, ADD COLUMN rider_secret_id BIGINT, ADD COLUMN api_v3_secret_id BIGINT, ADD COLUMN merchant_private_secret_id BIGINT, ADD COLUMN wechat_public_secret_id BIGINT, ADD COLUMN payment_enabled BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE wechat_config ADD CONSTRAINT fk_wx_user_secret FOREIGN KEY(user_secret_id) REFERENCES wechat_secret(id), ADD CONSTRAINT fk_wx_merchant_secret FOREIGN KEY(merchant_secret_id) REFERENCES wechat_secret(id), ADD CONSTRAINT fk_wx_rider_secret FOREIGN KEY(rider_secret_id) REFERENCES wechat_secret(id), ADD CONSTRAINT fk_wx_v3_secret FOREIGN KEY(api_v3_secret_id) REFERENCES wechat_secret(id), ADD CONSTRAINT fk_wx_private_secret FOREIGN KEY(merchant_private_secret_id) REFERENCES wechat_secret(id), ADD CONSTRAINT fk_wx_public_secret FOREIGN KEY(wechat_public_secret_id) REFERENCES wechat_secret(id);
